contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseTokenA,
        address nftA,
        uint128 virtualBaseTokenReservesA,
        uint128 virtualNftReservesA,
        uint56 changeFeeA,
        uint16 feeRateA,
        bytes32 merkleRootA,
        bool useStolenNftOracleA,
        bool payRoyaltiesA,
        address baseTokenB,
        address nftB,
        uint128 virtualBaseTokenReservesB,
        uint128 virtualNftReservesB,
        uint56 changeFeeB,
        uint16 feeRateB,
        bytes32 merkleRootB,
        bool useStolenNftOracleB,
        bool payRoyaltiesB
    ) public {
        require(feeRateA <= 5000);
        require(feeRateB <= 5000);

        bool firstReverted;
        try c.initialize(
            baseTokenA,
            nftA,
            virtualBaseTokenReservesA,
            virtualNftReservesA,
            changeFeeA,
            feeRateA,
            merkleRootA,
            useStolenNftOracleA,
            payRoyaltiesA
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.initialize(
            baseTokenB,
            nftB,
            virtualBaseTokenReservesB,
            virtualNftReservesB,
            changeFeeB,
            feeRateB,
            merkleRootB,
            useStolenNftOracleB,
            payRoyaltiesB
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            !firstReverted &&
            secondReverted &&
            c.initialized() &&
            c.baseToken() == baseTokenA &&
            c.nft() == nftA &&
            c.virtualBaseTokenReserves() == virtualBaseTokenReservesA &&
            c.virtualNftReserves() == virtualNftReservesA &&
            c.changeFee() == changeFeeA &&
            c.feeRate() == feeRateA &&
            c.merkleRoot() == merkleRootA &&
            c.useStolenNftOracle() == useStolenNftOracleA &&
            c.payRoyalties() == payRoyaltiesA
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 outputWeight, uint256 inputAmount) public payable {
        (uint256 buyNet, uint256 buyFee, uint256 buyProtocol) = c.buyQuote(outputWeight);
        uint128 beforeVirtualNft = c.virtualNftReserves();
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        (uint256 sellNet, uint256 sellFee, uint256 sellProtocol) = c.sellQuote(outputWeight);

        require(
            beforeVirtualNft > 0 &&
            outputWeight > 0 &&
            buyNet >= buyFee + buyProtocol &&
            sellNet > sellFee + sellProtocol &&
            inputAmount >= sellFee + sellProtocol &&
            inputAmount <= buyNet &&
            beforeVirtualNft > outputWeight
        );

        require(address(this).balance >= inputAmount, "balance");
        uint256[] memory tokenIds = new uint256[](1);
        uint256[] memory tokenWeights = new uint256[](1);
        tokenIds[0] = 1;
        tokenWeights[0] = outputWeight;
        C.MerkleMultiProof memory proof = C.MerkleMultiProof(new bytes32[](0), new bool[](0));

        uint256 valueBoughtNfts = outputWeight;

        uint256[] memory sellTokenIds = new uint256[](1);
        uint256[] memory sellTokenWeights = new uint256[](1);
        sellTokenIds[0] = 1;
        sellTokenWeights[0] = 0;

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buy{value: inputAmount}(
            tokenIds,
            tokenWeights,
            proof
        );

        assert(
            (uint256(c.virtualNftReserves()) == uint256(beforeVirtualNft) - valueBoughtNfts) &&
            (uint256(c.virtualBaseTokenReserves()) == uint256(beforeVirtualBase) + netInputAmount - feeAmount - protocolFeeAmount)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 id0, uint256 weight0, uint256 amount) public payable {
        require(amount > 0, "amount");
        require(address(this).balance >= amount, "balance");

        uint128 beforeNft = c.virtualNftReserves();
        uint128 beforeBase = c.virtualBaseTokenReserves();

        uint256[] memory tokenIds = new uint256[](1);
        uint256[] memory tokenWeights = new uint256[](1);
        tokenIds[0] = id0;
        tokenWeights[0] = weight0;

        uint256 expectedNftWeight;
        bool reverted;
        {
            uint256[] memory settleIds = tokenIds;
            uint256[] memory settleWeights = tokenWeights;
            try c.buy{value: amount}(
                settleIds,
                settleWeights,
                C.MerkleMultiProof(new bytes32[](0), new bool[](0))
            ) returns (uint256 netInput, uint256 fee, uint256 protocolFee) {
                reverted = false;
                expectedNftWeight = netInput - fee - protocolFee;
            } catch {
                reverted = true;
            }
        }

        assert(
            reverted
                ? (
                    c.virtualNftReserves() == beforeNft &&
                    c.virtualBaseTokenReserves() == beforeBase
                )
                : (
                    uint256(c.virtualNftReserves()) == uint256(beforeNft) - weight0 &&
                    uint256(c.virtualBaseTokenReserves()) == uint256(beforeBase) + expectedNftWeight
                )
        );
    }
}

